const e = $('Failure trigger').first().json || {};
const s = $input.first().json || {};
const wf = (e.workflow && e.workflow.name) || 'A workflow';
const err = String((e.execution && e.execution.error && e.execution.error.message) || 'Unknown error').slice(0, 300);
const node = (e.execution && e.execution.lastNodeExecuted) || '';
const at = new Date().toISOString();
const prev = (s.status && s.status.last_error) || {};
const repeat = prev.workflow === wf && prev.message === err && prev.at && Date.now() - new Date(prev.at).getTime() < 3600e3;
const url = s.alerts && s.alerts.discord && s.alerts.discord.webhook_url;
const enabled = !!(s.alerts && s.alerts.enabled === true);
return [{ json: {
  status_patch: { last_error: { workflow: wf, node, message: err, at }, errors_total: ((s.status && s.status.errors_total) || 0) + 1 },
  alert: !!url && enabled && !repeat,
  webhook_url: url || null,
  content: 'Workflow failed: ' + wf + (node ? '\nStep: ' + node : '') + '\n' + err + '\nSee Sources in the Lead Radar dashboard.',
} }];
